package dev.igor.motonav.share

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * Geohash vectors, from a source independent of the decoder: the two from
 * Wikipedia (`ezs42`, `u4pruydqqvj`) and one from São Paulo generated by a
 * separate encoder, in Python, for the fixtures point (Congonhas).
 */
class GeohashTest {

    @Test
    fun `ezs42 from wikipedia`() {
        val point = Geohash.decode("ezs42")!!

        assertEquals(42.605, point.lat, 0.03)
        assertEquals(-5.603, point.lon, 0.03)
    }

    @Test
    fun `u4pruydqqvj from wikipedia`() {
        val point = Geohash.decode("u4pruydqqvj")!!

        assertEquals(57.64911, point.lat, 1e-5)
        assertEquals(10.40744, point.lon, 1e-5)
    }

    @Test
    fun `congonhas in nine characters`() {
        val point = Geohash.decode("6gycd6cv5")!!

        assertEquals(-23.626600, point.lat, 1e-4)
        assertEquals(-46.656400, point.lon, 1e-4)
    }

    @Test
    fun `character outside the alphabet does not decode`() {
        assertNull(Geohash.decode("6gyca"))
        assertNull(Geohash.decode(""))
    }

    @Test
    fun `uppercase counts as lowercase`() {
        assertEquals(Geohash.decode("6gycd6cv5"), Geohash.decode("6GYCD6CV5"))
    }
}
